mapper.select:
SELECT o.* 
FROM orders o
LEFT JOIN customers c ON o.customer_id = c.id
WHERE o.tenant_id = #{tenantId}

    AND (o.order_number LIKE CONCAT('%', #{searchTerm}, '%') 
         OR CONCAT(COALESCE(c.first_name, ''), ' ', COALESCE(c.last_name, '')) LIKE CONCAT('%', #{searchTerm}, '%'))


    AND o.payment_status = #{paymentStatus}


    AND o.order_status = #{orderStatus}


    AND o.customer_id = #{customerId}


    AND DATE(o.created_at) >= #{startDate}


    AND DATE(o.created_at) <= #{endDate}

ORDER BY o.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM orders o
LEFT JOIN customers c ON o.customer_id = c.id
WHERE o.tenant_id = #{tenantId}

    AND (o.order_number LIKE CONCAT('%', #{searchTerm}, '%') 
         OR CONCAT(COALESCE(c.first_name, ''), ' ', COALESCE(c.last_name, '')) LIKE CONCAT('%', #{searchTerm}, '%'))


    AND o.payment_status = #{paymentStatus}


    AND o.order_status = #{orderStatus}


    AND o.customer_id = #{customerId}


    AND DATE(o.created_at) >= #{startDate}


    AND DATE(o.created_at) <= #{endDate}

SELECT id, total_amount, payment_status, order_status, created_at
FROM orders 
WHERE tenant_id = #{tenantId} 
AND DATE(created_at) = #{date}
ORDER BY created_at DESC

SELECT id, total_amount, payment_status, order_status, created_at
FROM orders 
WHERE tenant_id = #{tenantId} 
AND DATE(created_at) BETWEEN #{startDate} AND #{endDate}
ORDER BY created_at DESC
